import java.io.*;import java.nio.file.*;import java.util.*;
public class IdeaRegressionSuite { public static void main(String[] args)throws Exception {String[] names={"CampusPaymentChannelIntegration","FinanceIntegration","FinanceEvidenceIntegration","WalletTemplateRenderCheck","PermissionIntegration"};Path out=Paths.get(".local/idea-validation");Files.createDirectories(out);int failed=0,total=0;StringBuilder report=new StringBuilder();for(String name:names){Path log=out.resolve(name+".log");Process p=new ProcessBuilder(System.getProperty("java.home")+"/bin/java.exe","-Dfile.encoding=UTF-8","-cp",System.getProperty("java.class.path"),name).redirectErrorStream(true).redirectOutput(log.toFile()).start();boolean ended=p.waitFor(90,java.util.concurrent.TimeUnit.SECONDS);if(!ended)p.destroyForcibly();int code=ended?p.exitValue():124;long checks=Files.readAllLines(log,java.nio.charset.StandardCharsets.UTF_8).stream().filter(s->s.startsWith("PASS ")&&!s.startsWith("PASS TOTAL")).count();total+=checks;if(code!=0)failed++;String line=name+" exit="+code+" checks="+checks;System.out.println(line);report.append(line).append("\n");}String summary="TOTAL checks="+total+" failed suites="+failed;System.out.println(summary);report.append(summary);Files.write(out.resolve("results.txt"),report.toString().getBytes("UTF-8"));if(failed>0)throw new AssertionError(summary);}}
